action.command:
cd /workspace && docker compose exec -T backend node -e '
const SA = process.env.SUPER_ADMIN_API_KEY || "";
(async () => {
  // 1. super-admin: list schools (read-only check that API + key work)
  const list = await fetch("http://backend:4000/api/v1/school/list-schools", { headers: { "x-super-admin-api-key": SA } });
  console.log("list-schools (super-admin) HTTP", list.status, (await list.text()).slice(0,150));

  // 2. media route present on API domain (guide requires /media)
  const media = await fetch("http://backend:4000/media", { redirect: "manual" });
  console.log("/media HTTP", media.status, media.headers.get("content-type"));

  // 3. well-known app links
  const wk = await fetch("http://backend:4000/.well-known/apple-app-site-association", { redirect: "manual" });
  console.log("/.well-known/apple-app-site-association HTTP", wk.status, (await wk.text()).slice(0,120));

  // 4. worker health
  const wh = await fetch("http://worker:4001/health");
  console.log("worker /health HTTP", wh.status, (await wh.text()).slice(0,150));
})();
' 2>&1 | head -30

